 * "reinstall rotates credentials, never keeps the old ones" rule
 * `reinstall()`'s own comment (worker/index.ts) applies to the VPS root
 * password.
 */
export function buildGameSetupScript(server: {
  /** Needed by fivem (per-server derived secrets); every real caller passes the Server row. */
  id?: string;
  osTemplate: { setupScript: string | null; family: string | null };
  gameVariant?: string | null;
  gameConfig?: unknown;
  /** Minecraft only: an exact mirrored jar to stage + pin (worker/mcjar-pin.ts#mcJarPinForSetup), or null for upstream behaviour. */
  __mcJarPin?: PinPlan | null;
  /** Terraria only: image tag + optional mirror tarball for the fresh install (worker/terraria-target.ts#terrariaSetupPlan). */
  __terrariaPlan?: { version: string; mirror: { url: string; sha256: string } | null } | null;
  // The VM's real RAM (GamePlan.ramMB, else the VPS plan's). Optional: a
  // caller that doesn't load the plan (GAME_REINSTALL today) keeps the
  // catalog's heap exactly as before.
  // Index signature: callers pass their own partial selects (GAME_REINSTALL's
  // gamePlan is `{ gameFamily }`), which TS's weak-type check would reject.
  gamePlan?: { ramMB?: number | null; [k: string]: unknown } | null;
  plan?: { ramMB?: number | null; [k: string]: unknown } | null;
}): string | null {
  if (!server.osTemplate.setupScript) return null;
  const scriptWithDocker = skipDockerInstallIfPresent(server.osTemplate.setupScript);
  const scriptWithVariant = applyGameVariant(scriptWithDocker, server.osTemplate.family, server.gameVariant ?? null);
  const scriptWithEnv = applyGameConfigEnv(
    scriptWithVariant,
    server.osTemplate.family,
    server.gameConfig as Record<string, unknown> | null,
  );
  // Terraria (2026-10-02): its settings are launch args + a TShock config.json, not `-e` env, so
  // applyGameConfigEnv cannot express them — bake them in so a fresh install / reinstall starts configured.
  const scriptWithTerrariaConfig = (() => {
    if (server.osTemplate.family !== "terraria" || !server.gameConfig) return scriptWithEnv;
    const v = validateConfig("terraria", server.gameConfig as Record<string, unknown>);
    return v.ok ? applyTerrariaSetup(scriptWithEnv, v.values) : scriptWithEnv;
  })();
  // Terraria image: pin the tag and stage the tarball from our mirror when we have it (registry pull is the fallback).
  const scriptWithConfig = server.osTemplate.family === "terraria" ? applyTerrariaImage(scriptWithTerrariaConfig, server.__terrariaPlan) : scriptWithTerrariaConfig;
  // Minecraft server-software mirror (lib/mcjars/pin.ts): stage the exact jar on
  // the guest and run it pinned, so container restarts never contact upstream
  // (2026-10-01 PaperMC outage). A pinned LATEST resolves to the concrete
  // version, and the Java image follows THAT version.
  const pin = server.osTemplate.family === "minecraft" ? server.__mcJarPin ?? null : null;
  const scriptWithPin = pin ? applyPinToSetupScript(scriptWithConfig, pin, server.gameVariant ?? "vanilla") : scriptWithConfig;
  const scriptWithJavaImageRaw = applyMinecraftJavaImage(
    scriptWithPin,
    server.osTemplate.family,
    pin
      ? { ...((server.gameConfig as Record<string, unknown> | null) ?? {}), VERSION: pin.mcVersion }
      : (server.gameConfig as Record<string, unknown> | null),
  );
  const scriptWithJavaImage = rotateWeakAdminSecrets(
    applyMinecraftHeap(
      scriptWithJavaImageRaw,
      server.osTemplate.family,
      server.gameConfig as Record<string, unknown> | null,
      (server.gamePlan?.ramMB as number | null | undefined) ?? (server.plan?.ramMB as number | null | undefined) ?? null,
    ),
  );
  // dayz (Wave 11, 2026-09-24): shared Nxeon-owned Steam credential, not a
  // freshly-generated per-server secret — see lib/dayz-steam.ts. Unconfigured
  // resolves to an empty object, so applyGameControlSecrets' "only touches a
  // key already present" discipline leaves the setupScript's blank
  // placeholders exactly as seeded (honest SteamCMD anonymous-login failure
  // rather than silently proceeding). lib/game-order.ts also refuses new DayZ
  // orders while unconfigured, so this branch should never actually run
  // against an unconfigured account in production.
  const dayzCreds = dayzSteamCredentials();
  const dayzSecrets: Record<string, string> = dayzCreds ? { USERNAME: dayzCreds.username, PASSWRD: dayzCreds.password } : {};
  const scriptWithSecrets =
    server.osTemplate.family === "palworld"
      ? applyGameControlSecrets(scriptWithJavaImage, { ADMIN_PASSWORD: generatePassword() })
      : server.osTemplate.family === "rust"
        ? applyGameControlSecrets(scriptWithJavaImage, { RUST_RCON_PASSWORD: generatePassword() })
        : server.osTemplate.family === "cs2"
          ? applyGameControlSecrets(scriptWithJavaImage, { CS2_RCONPW: generatePassword() })
          : server.osTemplate.family === "armareforger"
            ? applyGameControlSecrets(scriptWithJavaImage, { ADMIN_PASSWORD: generatePassword() })
            : server.osTemplate.family === "dayz"
              ? applyGameControlSecrets(scriptWithJavaImage, dayzSecrets)
              : scriptWithJavaImage;
  // fivem (2026-10-01, feature-flagged — lib/fivem.ts): server.cfg/secrets.cfg/
  // runtime.env are FILES rendered from gameConfig + the customer's sealed BYO
  // licence key + per-server derived RCON/players-token secrets, written in
  // place of the template's placeholder line (lib/fivem-install.ts).
  const scriptWithFivem =
    server.osTemplate.family === "fivem"
      ? (() => {
          if (!server.id) throw new Error("fivem setup needs the server id (per-server secrets)");
          return applyFivemSetup(scriptWithSecrets, "fivem", {
            gameConfig: server.gameConfig as Record<string, unknown> | null,
            planSlots: (server.gamePlan?.slots as number | null | undefined) ?? null,
            licenseKey: fivemLicenseKey(server.gameConfig),
            ...deriveFivemSecrets(server.id),
          });
        })()
      : scriptWithSecrets;
  const wrapped = wrapDockerGameService(scriptWithFivem, server.osTemplate.family);
  const mirror = registryMirrorPrelude(process.env.NXEON_DOCKER_REGISTRY_MIRROR);
  return mirror ? `${mirror}\n${wrapped}` : wrapped;
