async function imageId(g: Guest, ref: string): Promise<string | null> {
  const r = await g.exec(`docker image inspect ${shq(ref)} --format '{{.Id}}'`);
  const id = r.stdout.trim();
  return r.code === 0 && /^sha256:[a-f0-9]{64}$/.test(id) ? id : null;
}

/**
 * `docker image inspect --format {{.Id}}` is the image CONFIG digest on the classic image store, but on Docker 29's default
 * containerd image store (what every guest built from get.docker.com runs) it is the registry INDEX digest of what was pulled.
 * Both identify the same verified build, so accept either; anything else is a different image and is refused.
 */
function idMatches(got: string, t: UpdateTarget): boolean {
  return got === t.imageId || (!!t.indexDigest && got === t.indexDigest);
}

/** Get the target image onto the guest. Returns where it came from, or an error string. */
async function ensureImage(g: Guest, t: UpdateTarget): Promise<{ ok: true; source: string } | { ok: false; error: string }> {
  const ref = terrariaImageRef(t.tshock);
  const have = await imageId(g, ref);
  if (have && (!t.imageId || idMatches(have, t))) return { ok: true, source: "present" };
  let source = "";
  if (t.mirror) {
    const tar = "/root/nx-tshock-image.tar";
    const dl = await g.exec(`curl -fsSL --retry 3 --max-time 900 -o ${tar} ${shq(t.mirror.url)}`, 960_000);
    const sum = dl.code === 0 ? await g.exec(`echo ${shq(`${t.mirror.sha256}  ${tar}`)} | sha256sum -c -`) : null;
    const loaded = sum && sum.code === 0 ? await g.exec(`docker load -i ${tar}`, 600_000) : null;
    await g.exec(`rm -f ${tar}`).catch(() => undefined);
    if (loaded && loaded.code === 0) source = "mirror";
  }
  if (!source) {
    // Registry fallback. By digest when we know it (immutable), then tag it with the explicit version.
    const k = terrariaKnown(t.tshock);
    if (k && t.indexDigest) {
      const by = terrariaImageByDigest({ ...k, indexDigest: t.indexDigest });
      const p = await g.exec(`docker pull ${shq(by)}`, 900_000);
      if (p.code === 0 && (await g.exec(`docker tag ${shq(by)} ${shq(ref)}`)).code === 0) source = "registry";
    } else {
      const p = await g.exec(`docker pull ${shq(ref)}`, 900_000);
      if (p.code === 0) source = "registry";
    }
  }
  if (!source) return { ok: false, error: "Could not download the new Terraria server image, so nothing was changed." };
  const got = await imageId(g, ref);
  if (!got) return { ok: false, error: "The new Terraria server image did not load, so nothing was changed." };
  if (t.imageId && !idMatches(got, t)) {
    return { ok: false, error: "The downloaded server image did not match the expected build, so it was not used. Nothing was changed." };
  }
  return { ok: true, source };
}

