  // marker reserved for exactly this row shape, accepted here as an alternative.
  if (!gp || (!gp.active && gp.sortOrder !== CUSTOM_PLAN_SORT_ORDER)) {
    throw new GameOrderError("That game plan isn't available.");
  }
  if (!gp.basePlan?.active && gp.basePlan?.sortOrder !== CUSTOM_PLAN_SORT_ORDER) {
