src='''// Disk footprint of every game family's Docker image on a fresh guest.
//
// WHY (2026-10-04, l4d2-rod4xk): a Left 4 Dead 2 order could not provision. Its image
// (left4devops/l4d2, ~5 GB compressed, the whole game baked in) failed to unpack on a 20 GB
// plan. Guests run Docker 29 from get.docker.com, whose DEFAULT is the containerd image store:
// it keeps the compressed blobs AND the unpacked snapshots (about 2x the image) on a root disk
// that already holds the OS and a RAM-sized swapfile. The classic overlay2 store keeps only the
// unpacked layers. New guests are now switched to the classic store before the first pull
// (lib/guest-docker.ts); this table lets CI and the setup script check that a plan's disk fits.
//
// SOURCES / HONESTY: `compressedGB` is the sum of the amd64 manifest's layer sizes read from the
// registry with `skopeo inspect --raw` on 2026-10-04 (read-only; GiB). `unpackedGB` is an ESTIMATE
// (layers uncompress ~2x for small base-OS images, ~1.15x for image layers that are mostly
// game data; l4d2 is pinned to the 6 GB the owner measured on the live VM). `gameFilesGB` is the
// approximate size of the dedicated-server files SteamCMD/the entrypoint downloads into the
// /opt volume on first start; it is NOT in the image, was NOT measured here, and comes from public
// dedicated-server install sizes, so treat it as a planning number. Refresh a row when an image
// changes shape (re-run skopeo inspect) rather than trusting it blindly.

export type GameImageFootprint = {
  image: string;
  /** Sum of the registry layer sizes (what the containerd store keeps on disk as blobs). */
  compressedGB: number;
  /** Estimated unpacked size (what both stores keep as snapshots / overlay2 layers). */
  unpackedGB: number;
  /** Approximate game files downloaded at first start into the data volume (not in the image). */
  gameFilesGB: number;
};

export const GAME_IMAGE_FOOTPRINT: Record<string, GameImageFootprint> = {
%BODY%
};

/** Ubuntu root filesystem + packages + dockerd state on a fresh guest, before any image (observed ~6 GB). */
export const GUEST_OS_BASE_GB = 6;
/** Images at or above this unpacked size get the in-guest free-space check before the pull. */
export const BIG_IMAGE_GB = 2;

export type ImageStore = "classic" | "containerd";

/** Disk the IMAGE alone occupies once pulled: classic keeps the unpacked layers, containerd also keeps the compressed blobs. */
export function imageDiskGB(family: string, store: ImageStore): number | null {
  const f = GAME_IMAGE_FOOTPRINT[family];
  if (!f) return null;
  return f.unpackedGB + (store === "containerd" ? f.compressedGB : 0);
}

/** Image plus the game files downloaded on first start (no OS), the number CI compares a plan's disk to. */
export function imageFootprintGB(family: string, store: ImageStore): number | null {
  const img = imageDiskGB(family, store);
  return img === null ? null : img + GAME_IMAGE_FOOTPRINT[family].gameFilesGB;
}

/**
 * The floor a plan's disk can never go under: OS + RAM-sized swapfile + the image alone on the
 * classic store (+1 GB slack). Deliberately excludes the estimated game files so it can run on the
 * order path without refusing a plan that has been selling fine; the full estimate is the CI test.
 */
export function hardMinDiskGB(family: string, ramMB: number): number | null {
  const img = imageDiskGB(family, "classic");
  return img === null ? null : Math.ceil(GUEST_OS_BASE_GB + ramMB / 1024 + img + 1);
}

/** GB the in-guest guard needs free before pulling this family's image, or null when no guard applies (small image / unknown family). */
export function pullGuardGB(family: string, store: ImageStore): number | null {
  const f = GAME_IMAGE_FOOTPRINT[family];
  if (!f || f.unpackedGB < BIG_IMAGE_GB) return null;
  return Math.ceil((imageDiskGB(family, store) as number) + 1);
}
'''.replace('%BODY%',body)
open('lib/game-image-footprint.ts','w').write(src)
E

