/**
 * In-guest free-space guard for a big image, spliced into the create loop's function body
 * (worker/game-variant.ts). Needs `nx_state`. Returns 1 (and writes the failed state the worker
 * reads) instead of retrying a pull that cannot fit for an hour.
 */
export function pullDiskGuardShell(image: string, classicGB: number, containerdGB: number): string {
  const q = `'${image.replace(/'/g, "'\\''")}'`;
  return [
    // Image already on the guest (a reinstall): nothing to pull, nothing to check.
    `  if ! docker image inspect ${q} >/dev/null 2>&1; then`,
    `  nx_need=${classicGB}; docker info --format '{{json .DriverStatus}}' 2>/dev/null | grep -q 'io.containerd.snapshotter' && nx_need=${containerdGB}`,
    `  nx_have=$(df -P -BG /var/lib/docker 2>/dev/null | awk 'NR==2{gsub(/G/,"",$4);print $4}'); [ -n "$nx_have" ] || nx_have=$(df -P -BG / | awk 'NR==2{gsub(/G/,"",$4);print $4}')`,
    `  if [ "\${nx_have:-0}" -lt "$nx_need" ]; then nx_state "failed: disk too small for this game image: need $nx_need GB, have $nx_have GB"; return 1; fi`,
    "  fi",
  ].join("\n");
}

export type StartupSample = {
  /** systemd NRestarts of the game unit, -1 unknown. */
  restarts: number;
  /** docker container state ("running" | "exited" | "restarting" | "created" | "missing" | "unknown"). */
  container: string;
  exitCode: number | null;
  /** Seconds the container's last run lasted (FinishedAt - StartedAt), null if unknown/running. */
  lastRunSeconds: number | null;
  /** Last line of /var/lib/nxeon/game-setup.state ("" when absent). */
  setupState: string;
  /** Is the in-guest setup script still running (pgrep)? */
  setupRunning: boolean;
  /** Recent game output (journal of the unit + docker logs tail). */
  log: string;
  /** Recent setup log tail (for setup failures). */
  setupLog?: string;
};

export type StartupVerdict =
  | { kind: "ok" }
  /** Keep waiting — nothing conclusive. */
  | { kind: "wait" }
  /** The in-guest setup died/failed before creating the container — re-run it (idempotent). */
  | { kind: "repair"; reason: string; lines: string[] }
  /** The game itself cannot start with this config — stop waiting now. */
  /** `recognised`: a known fatal line was seen (vs. restarts alone) — only those are not worth a retry. */
  | { kind: "fatal"; reason: string; lines: string[]; recognised: boolean };

/** Restarts of the unit since the check began that make an exit loop conclusive without a known fatal line. */
export const EARLY_CRASH_RESTARTS = 3;
/** With a recognisable fatal line in the output, two restarts are enough. */
export const EARLY_CRASH_RESTARTS_WITH_FATAL = 2;
/** A run shorter than this that ends is "exited on start". */
export const SHORT_RUN_SECONDS = 90;

/**
 * Decide, from one in-guest sample and the restart counter seen when the check
 * began, whether waiting longer can help. Positive evidence only: unknown
 * readings never produce "fatal".
 */
export function classifyStartup(baselineRestarts: number, s: StartupSample): StartupVerdict {
  const state = (s.setupState ?? "").trim();
  if (s.container === "missing") {
    if (s.setupRunning) return { kind: "wait" };
    // Setup is not running and there is no container: whatever the state file
    // says, waiting cannot produce a game. valheim-gjjrv9: `docker create`'s
    // implicit pull died, the script carried on and installed the unit, and
    // valheim.service restarted 85 times against "No such container".
    const setupTail = lastErrorLines(s.setupLog ?? "", 8);
    return {
      kind: "repair",
      reason:
        `the game container was never created (setup ${state ? `state "${state.replace(/^\S+\s+/, "")}"` : "left no state"}` +
        `${/No such container/i.test(s.log) ? "; the service is restarting against a container that does not exist" : ""})`,
      lines: setupTail.lines,
    };
  }
  if (s.restarts < 0 || baselineRestarts < 0) return { kind: "wait" };
  const delta = s.restarts - baselineRestarts;
  const errs = lastErrorLines(s.log, 8);
  const exitedFast = s.container !== "running" && s.lastRunSeconds !== null && s.lastRunSeconds < SHORT_RUN_SECONDS;
  if ((errs.matched && delta >= EARLY_CRASH_RESTARTS_WITH_FATAL) || delta >= EARLY_CRASH_RESTARTS) {
    const how =
      s.exitCode === 0
        ? "exits (with code 0) seconds after every start"
        : s.exitCode !== null
          ? `exits with code ${s.exitCode} after every start`
          : "keeps exiting after start";
    return {
      kind: "fatal",
      reason:
        `the game ${how} — systemd has restarted it ${delta} time(s) while we watched` +
        `${exitedFast && s.lastRunSeconds !== null ? `, last run lasted ${s.lastRunSeconds}s` : ""}`,
      lines: errs.lines,
      recognised: errs.matched,
    };
  }
  return { kind: "wait" };
}

/**
 * Shell test: is an in-guest setup run in progress? The setup header records
 * its PID (worker/game-variant.ts wrapDockerGameService); cloud-init still
 * running means the first-boot setup may not even have started yet. Never a
 * `pgrep -f` on the script name — that also matches the SSH command line
 * asking the question.
 */
export const SETUP_RUNNING_TEST =
  `{ nx_p=$(cat /var/lib/nxeon/game-setup.pid 2>/dev/null); [ -n "$nx_p" ] && kill -0 "$nx_p" 2>/dev/null; } || ` +
  `{ cloud-init status 2>/dev/null | grep -q 'status: running'; }`;

