// Static scan of the Prisma seed files for every game plan's disk and every game template's minDiskGB.
// The seeds are scripts (they connect to the DB on import), so they are read as text, not imported.
import { readdirSync, readFileSync } from "node:fs";
import { join } from "node:path";

const PRISMA = join(import.meta.dirname, "..", "prisma");

export type SeedPlan = { family: string; name: string; diskGB: number; ramMB: number; file: string };

export function scanSeedGameDisks(): { plans: SeedPlan[]; minDisk: Map<string, number> } {
  const plans: SeedPlan[] = [];
  const minDisk = new Map<string, number>();
  for (const file of readdirSync(PRISMA).filter((f) => /^(seed-.*|catalog)\.ts$/.test(f))) {
    const text = readFileSync(join(PRISMA, file), "utf8");
    // Plan rows: one object per line with gameFamily + ramMB + diskGB (seed-wave12-arma3 has no gameFamily on its tier lines).
    for (const line of text.split("\n")) {
      const fam = /gameFamily:\s*"([a-z0-9_]+)"/.exec(line)?.[1] ?? (file === "seed-wave12-arma3.ts" && /name:\s*"Arma 3/.test(line) ? "arma3" : null);
      const disk = /\bdiskGB:\s*(\d+)/.exec(line)?.[1];
      const ram = /\bramMB:\s*(\d+)/.exec(line)?.[1];
      const name = /name:\s*"([^"]+)"/.exec(line)?.[1] ?? "";
      if (fam && disk && ram && !/minDiskGB/.test(line)) plans.push({ family: fam, name, diskGB: Number(disk), ramMB: Number(ram), file });
    }
    // Template rows: `family: "x", ... minDiskGB: N`
    for (const m of text.matchAll(/family:\s*"([a-z0-9_]+)"[^\n]*?minDiskGB:\s*(\d+)/g)) {
      minDisk.set(m[1], Math.max(minDisk.get(m[1]) ?? 0, Number(m[2])));
    }
    for (const m of text.matchAll(/family:\s*"([a-z0-9_]+)",\s*\n\s*minDiskGB:\s*(\d+)/g)) {
      minDisk.set(m[1], Math.max(minDisk.get(m[1]) ?? 0, Number(m[2])));
    }
  }
  return { plans, minDisk };
}
