// Disk-fit + guest Docker image-store tests (l4d2-rod4xk, 2026-10-04).
// Docker 29's default containerd image store keeps every image twice (compressed + unpacked), which
// made a 5 GB game image unpackable on a 20 GB guest. Guests are now switched to the classic store
// before the first pull, and these tests keep plan disks honest against lib/game-image-footprint.ts.
import { test } from "node:test";
import assert from "node:assert/strict";
import { spawnSync } from "node:child_process";
import { mkdtempSync, mkdirSync, writeFileSync, readFileSync, existsSync, symlinkSync, chmodSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import {
  GAME_IMAGE_FOOTPRINT, GUEST_OS_BASE_GB, BIG_IMAGE_GB, imageFootprintGB, imageDiskGB, hardMinDiskGB, pullGuardGB,
} from "../lib/game-image-footprint.ts";
import { DOCKER_CLASSIC_STORE_SNIPPET, pullDiskGuardShell } from "../lib/guest-docker.ts";
import { buildGameSetupScript, registryMirrorPrelude } from "../worker/game-variant.ts";
import { scanSeedGameDisks } from "./_seed-game-disks.ts";

const { plans, minDisk } = scanSeedGameDisks();

// --- CI: every seeded game plan fits its family's image ------------------------------------------

/**
 * Plans that are ALREADY below max(OsTemplate.minDiskGB, classic image + game files) in the seeds.
 * They pre-date this check and the owner has not decided whether to raise them (money path, sold
 * plans), so they are pinned here instead of being silently changed. The test fails if one of
 * these stops being undersized (remove it) or if a NEW undersized plan appears (fix the plan).
 * Keys are `family:diskGB`.
 */
const KNOWN_UNDERSIZED: Record<string, string> = {
  "ark:20": "entry tier 20 GB < template minDiskGB 40",
  "arkasa:60": "60 GB < template minDiskGB 70",
  "conan:20": "entry tier 20 GB < template minDiskGB 30",
  "cs2:40": "40 GB < template minDiskGB 60 (also under the ~37 GB game files + OS)",
  "cs2:50": "50 GB < template minDiskGB 60",
  "dst:8": "8 GB < template minDiskGB 10",
  "eco:20": "20 GB < template minDiskGB 25",
  "empyrion:20": "20 GB < template minDiskGB 30",
  "kf2:15": "15 GB < template minDiskGB 20",
  "sandstorm:20": "20 GB < template minDiskGB 25",
  "sdtd:20": "20 GB < template minDiskGB 25",
  "sonsoftheforest:20": "20 GB < template minDiskGB 25",
  "soulmask:20": "20 GB < template minDiskGB 30",
  "theisle:30": "30 GB < template minDiskGB 40",
  "unturned:8": "8 GB < template minDiskGB 10",
  "vintagestory:8": "8 GB < template minDiskGB 10",
};

const rawNeed = (family: string) => Math.max(minDisk.get(family) ?? 0, imageFootprintGB(family, "classic") ?? 0);

test("the seed scan finds the game plans and templates it should", () => {
  assert.ok(plans.length > 200, `only ${plans.length} plan rows scanned`);
  assert.equal(minDisk.get("l4d2"), 30);
  assert.equal(minDisk.get("cs2"), 60);
});

test("every seeded game family has an image footprint row", () => {
  const missing = [...new Set(plans.map((p) => p.family))].filter((f) => !GAME_IMAGE_FOOTPRINT[f]);
  assert.deepEqual(missing, [], `add lib/game-image-footprint.ts rows (skopeo inspect --raw) for: ${missing.join(", ")}`);
});

test("every game plan disk >= max(template minDiskGB, classic-store image footprint), apart from the pinned known cases", () => {
  const fresh: string[] = [];
  const stillUndersized = new Set<string>();
  for (const p of plans) {
    const need = rawNeed(p.family);
    const key = `${p.family}:${p.diskGB}`;
    if (p.diskGB < need) {
      stillUndersized.add(key);
      if (!KNOWN_UNDERSIZED[key]) fresh.push(`${p.file}: "${p.name}" disk ${p.diskGB} GB < ${need.toFixed(1)} GB needed`);
    }
  }
  assert.deepEqual(fresh, [], "plan disk too small for its image (raise it, or the template minDiskGB/estimate is wrong)");
  const stale = Object.keys(KNOWN_UNDERSIZED).filter((k) => !stillUndersized.has(k));
  assert.deepEqual(stale, [], "these KNOWN_UNDERSIZED entries are fine now; remove them");
});

test("big baked images also fit OS + RAM-sized swapfile + the containerd store (guests still on it, e.g. old golden clones)", () => {
  for (const p of plans) {
    const f = GAME_IMAGE_FOOTPRINT[p.family];
    if (!f || f.unpackedGB < BIG_IMAGE_GB || f.gameFilesGB > 0) continue; // game baked in the image: the l4d2 shape
    const need = GUEST_OS_BASE_GB + p.ramMB / 1024 + (imageDiskGB(p.family, "containerd") as number);
    assert.ok(p.diskGB >= need, `${p.family} "${p.name}" ${p.diskGB} GB < ${need.toFixed(1)} GB (OS + swap + containerd image)`);
  }
});

test("l4d2 plans and template match production (30 / 35 / 35, minDiskGB 30)", () => {
  const l4 = plans.filter((p) => p.family === "l4d2" && /wave4/.test(p.file));
  assert.deepEqual(l4.map((p) => [p.ramMB, p.diskGB]), [[2048, 30], [3072, 35], [4096, 35]]);
  assert.equal(minDisk.get("l4d2"), 30);
  assert.ok(plans.filter((p) => p.family === "l4d2").every((p) => p.diskGB >= 30));
});

test("footprint helpers: classic keeps unpacked only, containerd adds the compressed blobs", () => {
  const l4 = GAME_IMAGE_FOOTPRINT.l4d2;
  assert.equal(imageDiskGB("l4d2", "classic"), l4.unpackedGB);
  assert.equal(imageDiskGB("l4d2", "containerd"), l4.unpackedGB + l4.compressedGB);
  assert.ok((imageDiskGB("l4d2", "containerd") as number) > 10 && (imageDiskGB("l4d2", "containerd") as number) < 12, "owner's ~11 GB for l4d2");
  assert.equal(imageDiskGB("nope", "classic"), null);
  assert.equal(pullGuardGB("minecraft", "classic"), null, "small images get no guard");
  assert.equal(pullGuardGB("l4d2", "classic"), 7);
  assert.equal(pullGuardGB("l4d2", "containerd"), 12);
});

test("hardMinDiskGB: only big images, counts OS + swap, and the old 20 GB l4d2 plan is exactly the kind it catches", () => {
  assert.equal(hardMinDiskGB("minecraft", 2048), null);
  assert.equal(hardMinDiskGB("l4d2", 2048), Math.ceil(6 + 2 + 6.0 + 1));
  assert.equal(hardMinDiskGB("l4d2", 1024) as number <= 30, true);
  for (const p of plans.filter((p) => GAME_IMAGE_FOOTPRINT[p.family])) {
    const floor = hardMinDiskGB(p.family, p.ramMB);
    if (floor !== null) assert.ok(p.diskGB >= floor, `${p.family} "${p.name}" ${p.diskGB} < hard floor ${floor}: ordering would be refused`);
  }
});

// --- guest scripts: store config + pre-pull guard (real bash, stubbed docker) ---------------------

type Env = { store?: "containerd" | "classic"; containers?: string; images?: string; daemonJson?: string; noDocker?: boolean };

function runSnippet(env: Env): { dir: string; json: string | null; calls: string[] } {
  const dir = mkdtempSync(join(tmpdir(), "nx-dstore-"));
  const bin = join(dir, "bin");
  mkdirSync(bin);
  for (const t of ["python3", "mkdir", "dirname", "grep", "cat", "mv", "rm"]) {
    const w = spawnSync("sh", ["-c", `command -v ${t}`], { encoding: "utf8" }).stdout.trim();
    if (w) symlinkSync(w, join(bin, t));
  }
  const stub = (name: string, body: string) => { writeFileSync(join(bin, name), `#!/bin/bash\n${body}\n`); chmodSync(join(bin, name), 0o755); };
  stub("sleep", "exit 0");
  stub("systemctl", `echo "systemctl $*" >> "${dir}/calls"; exit 0`);
  if (!env.noDocker) {
    writeFileSync(join(dir, "store"), env.store ?? "containerd");
    writeFileSync(join(dir, "containers"), env.containers ?? "");
    writeFileSync(join(dir, "images"), env.images ?? "");
    stub("docker", [
      `case "$1 $2" in`,
      `  "info --format") if [ "$(cat "${dir}/store")" = containerd ]; then echo '[["driver-type","io.containerd.snapshotter.v1"]]'; else echo '[["Backing Filesystem","extfs"]]'; fi ;;`,
      `  "info "*|"info ") exit 0 ;;`,
      `  "ps -aq") cat "${dir}/containers" ;;`,
      `  "image ls") cat "${dir}/images" ;;`,
      `esac`,
    ].join("\n"));
  }
  const json = join(dir, "etc", "daemon.json");
  if (env.daemonJson !== undefined) { mkdirSync(join(dir, "etc")); writeFileSync(json, env.daemonJson); }
  const r = spawnSync("/bin/bash", ["-c", DOCKER_CLASSIC_STORE_SNIPPET], {
    encoding: "utf8", env: { PATH: bin, NX_DOCKER_DAEMON_JSON: json },
  });
  assert.equal(r.status, 0, r.stderr);
  const calls = existsSync(join(dir, "calls")) ? readFileSync(join(dir, "calls"), "utf8").split("\n").filter(Boolean) : [];
  return { dir, json: existsSync(json) ? readFileSync(json, "utf8") : null, calls };
}

test("store snippet: fresh guest without Docker gets the classic-store daemon.json before the install", () => {
  const r = runSnippet({ noDocker: true });
  try { assert.deepEqual(JSON.parse(r.json!), { features: { "containerd-snapshotter": false } }); assert.deepEqual(r.calls, []); } finally { rmSync(r.dir, { recursive: true, force: true }); }
});

test("store snippet: Docker present but empty (containerd store) is switched and restarted once", () => {
  const r = runSnippet({});
  try {
    assert.deepEqual(JSON.parse(r.json!), { features: { "containerd-snapshotter": false } });
    assert.deepEqual(r.calls, ["systemctl restart docker"]);
  } finally { rmSync(r.dir, { recursive: true, force: true }); }
});

test("store snippet: a guest with images or containers is never touched (switching hides them)", () => {
  for (const env of [{ images: "sha256:abc\n" }, { containers: "deadbeef\n" }] as Env[]) {
    const r = runSnippet(env);
    try { assert.equal(r.json, null, "daemon.json must not be written"); assert.deepEqual(r.calls, []); } finally { rmSync(r.dir, { recursive: true, force: true }); }
  }
});

test("store snippet: already on the classic store is a no-op; merging keeps unrelated daemon.json keys and is idempotent", () => {
  const a = runSnippet({ store: "classic" });
  try { assert.equal(a.json, null); assert.deepEqual(a.calls, []); } finally { rmSync(a.dir, { recursive: true, force: true }); }
  const orig = JSON.stringify({ "registry-mirrors": ["http://10.20.0.1:5000"], "log-driver": "json-file" });
  const b = runSnippet({ daemonJson: orig });
  try {
    const j = JSON.parse(b.json!);
    assert.deepEqual(j["registry-mirrors"], ["http://10.20.0.1:5000"]);
    assert.equal(j["log-driver"], "json-file");
    assert.equal(j.features["containerd-snapshotter"], false);
  } finally { rmSync(b.dir, { recursive: true, force: true }); }
  const c = runSnippet({ daemonJson: JSON.stringify({ features: { "containerd-snapshotter": false }, x: 1 }), store: "classic" });
  try { assert.deepEqual(JSON.parse(c.json!), { features: { "containerd-snapshotter": false }, x: 1 }); } finally { rmSync(c.dir, { recursive: true, force: true }); }
  const d = runSnippet({ daemonJson: "{not json" });
  try { assert.equal(d.json, "{not json", "an unparsable daemon.json is left alone"); } finally { rmSync(d.dir, { recursive: true, force: true }); }
});

test("built game setup scripts carry the store snippet before the install, valid bash, and the l4d2 guard only for big images", () => {
  const l4 = buildGameSetupScript({
    id: "x", osTemplate: { family: "l4d2", setupScript: "curl -fsSL https://get.docker.com | sh && mkdir -p /opt/l4d2 && docker run -d --name l4d2 --restart unless-stopped -p 27015:27015 -v /opt/l4d2/cfg:/cfg left4devops/l4d2:latest" },
  })!;
  assert.ok(l4.indexOf("nx_classic_store || true") < l4.indexOf("get.docker.com"));
  assert.match(l4, /failed: disk too small for this game image: need \$nx_need GB, have \$nx_have GB/);
  assert.match(l4, /nx_need=7;.*nx_need=12/s);
  assert.equal(spawnSync("bash", ["-n", "-c", l4], { encoding: "utf8" }).status, 0);
  const mc = buildGameSetupScript({
    id: "x", osTemplate: { family: "minecraft", setupScript: "curl -fsSL https://get.docker.com | sh && docker run -d --name mc -e EULA=TRUE -v /opt/mc:/data itzg/minecraft-server:java21" },
  })!;
  assert.doesNotMatch(mc, /disk too small/);
  assert.match(mc, /docker create --name mc --log-opt max-size=10m/, "the docker run is still rewritten");
  assert.equal(spawnSync("bash", ["-n", "-c", mc], { encoding: "utf8" }).status, 0);
  assert.match(registryMirrorPrelude("http://10.20.0.1:5000")!, /containerd-snapshotter/);
});

test("pre-pull guard: fails fast with the clear message when free space is short, passes when it fits, skips when the image is present", () => {
  const run = (freeGB: number, imagePresent: boolean, store: "containerd" | "classic") => {
    const dir = mkdtempSync(join(tmpdir(), "nx-guard-"));
    const bin = join(dir, "bin");
    mkdirSync(bin);
    const w = (n: string, b: string) => { writeFileSync(join(bin, n), `#!/bin/bash\n${b}\n`); chmodSync(join(bin, n), 0o755); };
    w("df", `printf 'Filesystem 1G-blocks Used Available Use%% Mounted on\\n/dev/sda1 40G 1G ${freeGB}G 5%% /\\n'`);
    w("docker", `case "$1" in info) echo '${store === "containerd" ? '[["driver-type","io.containerd.snapshotter.v1"]]' : "[]"}';; image) ${imagePresent ? "exit 0" : "exit 1"};; esac`);
    const script = `nx_state() { echo "$*"; }\nf() {\n${pullDiskGuardShell("left4devops/l4d2:latest", 7, 12)}\n  echo FITS\n}\nf`;
    const r = spawnSync("/bin/bash", ["-c", script], { encoding: "utf8", env: { PATH: `${bin}:/usr/bin:/bin` } });
    rmSync(dir, { recursive: true, force: true });
    return r.stdout.trim();
  };
  assert.equal(run(9, false, "containerd"), "failed: disk too small for this game image: need 12 GB, have 9 GB");
  assert.equal(run(9, false, "classic"), "FITS");
  assert.equal(run(5, false, "classic"), "failed: disk too small for this game image: need 7 GB, have 5 GB");
  assert.equal(run(30, false, "containerd"), "FITS");
  assert.equal(run(2, true, "containerd"), "FITS", "a reinstall with the image already on disk must not be refused");
});
