  "theisle:30": "30 GB < template minDiskGB 40",
  "unturned:8": "8 GB < template minDiskGB 10",
  "vintagestory:8": "8 GB < template minDiskGB 10",
};

const rawNeed = (family: string) => Math.max(minDisk.get(family) ?? 0, imageFootprintGB(family, "classic") ?? 0);

test("the seed scan finds the game plans and templates it should", () => {
  assert.ok(plans.length > 200, `only ${plans.length} plan rows scanned`);
  assert.equal(minDisk.get("l4d2"), 30);
  assert.equal(minDisk.get("cs2"), 60);
});

test("every seeded game family has an image footprint row", () => {
  const missing = [...new Set(plans.map((p) => p.family))].filter((f) => !GAME_IMAGE_FOOTPRINT[f]);
  assert.deepEqual(missing, [], `add lib/game-image-footprint.ts rows (skopeo inspect --raw) for: ${missing.join(", ")}`);
});

test("every game plan disk >= max(template minDiskGB, classic-store image footprint), apart from the pinned known cases", () => {
  const fresh: string[] = [];
  const stillUndersized = new Set<string>();
  for (const p of plans) {
    const need = rawNeed(p.family);
    const key = `${p.family}:${p.diskGB}`;
    if (p.diskGB < need) {
      stillUndersized.add(key);
      if (!KNOWN_UNDERSIZED[key]) fresh.push(`${p.file}: "${p.name}" disk ${p.diskGB} GB < ${need.toFixed(1)} GB needed`);
    }
  }
  assert.deepEqual(fresh, [], "plan disk too small for its image (raise it, or the template minDiskGB/estimate is wrong)");
  const stale = Object.keys(KNOWN_UNDERSIZED).filter((k) => !stillUndersized.has(k));
  assert.deepEqual(stale, [], "these KNOWN_UNDERSIZED entries are fine now; remove them");
});

test("big baked images also fit OS + RAM-sized swapfile + the containerd store (guests still on it, e.g. old golden clones)", () => {
  for (const p of plans) {
    const f = GAME_IMAGE_FOOTPRINT[p.family];
    if (!f || f.unpackedGB < BIG_IMAGE_GB || f.gameFilesGB > 0) continue; // game baked in the image: the l4d2 shape
    const need = GUEST_OS_BASE_GB + p.ramMB / 1024 + (imageDiskGB(p.family, "containerd") as number);
    assert.ok(p.diskGB >= need, `${p.family} "${p.name}" ${p.diskGB} GB < ${need.toFixed(1)} GB (OS + swap + containerd image)`);
  }
});

test("l4d2 plans and template match production (30 / 35 / 35, minDiskGB 30)", () => {
  const l4 = plans.filter((p) => p.family === "l4d2" && /wave4/.test(p.file));
  assert.deepEqual(l4.map((p) => [p.ramMB, p.diskGB]), [[2048, 30], [3072, 35], [4096, 35]]);
  assert.equal(minDisk.get("l4d2"), 30);
  assert.ok(plans.filter((p) => p.family === "l4d2").every((p) => p.diskGB >= 30));
});

test("footprint helpers: classic keeps unpacked only, containerd adds the compressed blobs", () => {
  const l4 = GAME_IMAGE_FOOTPRINT.l4d2;
  assert.equal(imageDiskGB("l4d2", "classic"), l4.unpackedGB);
  assert.equal(imageDiskGB("l4d2", "containerd"), l4.unpackedGB + l4.compressedGB);
  assert.ok((imageDiskGB("l4d2", "containerd") as number) > 10 && (imageDiskGB("l4d2", "containerd") as number) < 12, "owner's ~11 GB for l4d2");
  assert.equal(imageDiskGB("nope", "classic"), null);
  assert.equal(pullGuardGB("minecraft", "classic"), null, "small images get no guard");
  assert.equal(pullGuardGB("l4d2", "classic"), 7);
  assert.equal(pullGuardGB("l4d2", "containerd"), 12);
