test("hardMinDiskGB: only big images, counts OS + swap, and the old 20 GB l4d2 plan is exactly the kind it catches", () => {
  assert.equal(hardMinDiskGB("minecraft", 2048), null);
  assert.equal(hardMinDiskGB("l4d2", 2048), Math.ceil(6 + 2 + 6.0 + 1));
  assert.equal(hardMinDiskGB("l4d2", 1024) as number <= 30, true);
  for (const p of plans.filter((p) => GAME_IMAGE_FOOTPRINT[p.family])) {
    const floor = hardMinDiskGB(p.family, p.ramMB);
    if (floor !== null) assert.ok(p.diskGB >= floor, `${p.family} "${p.name}" ${p.diskGB} < hard floor ${floor}: ordering would be refused`);
  }
});

// --- guest scripts: store config + pre-pull guard (real bash, stubbed docker) ---------------------

type Env = { store?: "containerd" | "classic"; containers?: string; images?: string; daemonJson?: string; noDocker?: boolean };

function runSnippet(env: Env): { dir: string; json: string | null; calls: string[] } {
  const dir = mkdtempSync(join(tmpdir(), "nx-dstore-"));
  const bin = join(dir, "bin");
  mkdirSync(bin);
  for (const t of ["python3", "mkdir", "dirname", "grep", "cat", "mv", "rm"]) {
    const w = spawnSync("sh", ["-c", `command -v ${t}`], { encoding: "utf8" }).stdout.trim();
    if (w) symlinkSync(w, join(bin, t));
  }
  const stub = (name: string, body: string) => { writeFileSync(join(bin, name), `#!/bin/bash\n${body}\n`); chmodSync(join(bin, name), 0o755); };
  stub("sleep", "exit 0");
  stub("systemctl", `echo "systemctl $*" >> "${dir}/calls"; exit 0`);
  if (!env.noDocker) {
    writeFileSync(join(dir, "store"), env.store ?? "containerd");
    writeFileSync(join(dir, "containers"), env.containers ?? "");
    writeFileSync(join(dir, "images"), env.images ?? "");
    stub("docker", [
      `case "$1 $2" in`,
      `  "info --format") if [ "$(cat "${dir}/store")" = containerd ]; then echo '[["driver-type","io.containerd.snapshotter.v1"]]'; else echo '[["Backing Filesystem","extfs"]]'; fi ;;`,
      `  "info "*|"info ") exit 0 ;;`,
      `  "ps -aq") cat "${dir}/containers" ;;`,
      `  "image ls") cat "${dir}/images" ;;`,
      `esac`,
    ].join("\n"));
  }
  const json = join(dir, "etc", "daemon.json");
  if (env.daemonJson !== undefined) { mkdirSync(join(dir, "etc")); writeFileSync(json, env.daemonJson); }
  const r = spawnSync("/bin/bash", ["-c", DOCKER_CLASSIC_STORE_SNIPPET], {
    encoding: "utf8", env: { PATH: bin, NX_DOCKER_DAEMON_JSON: json },
  });
  assert.equal(r.status, 0, r.stderr);
  const calls = existsSync(join(dir, "calls")) ? readFileSync(join(dir, "calls"), "utf8").split("\n").filter(Boolean) : [];
  return { dir, json: existsSync(json) ? readFileSync(json, "utf8") : null, calls };
}

test("store snippet: fresh guest without Docker gets the classic-store daemon.json before the install", () => {
  const r = runSnippet({ noDocker: true });
  try { assert.deepEqual(JSON.parse(r.json!), { features: { "containerd-snapshotter": false } }); assert.deepEqual(r.calls, []); } finally { rmSync(r.dir, { recursive: true, force: true }); }
});

test("store snippet: Docker present but empty (containerd store) is switched and restarted once", () => {
  const r = runSnippet({});
  try {
    assert.deepEqual(JSON.parse(r.json!), { features: { "containerd-snapshotter": false } });
    assert.deepEqual(r.calls, ["systemctl restart docker"]);
  } finally { rmSync(r.dir, { recursive: true, force: true }); }
});

test("store snippet: a guest with images or containers is never touched (switching hides them)", () => {
  for (const env of [{ images: "sha256:abc\n" }, { containers: "deadbeef\n" }] as Env[]) {
    const r = runSnippet(env);
    try { assert.equal(r.json, null, "daemon.json must not be written"); assert.deepEqual(r.calls, []); } finally { rmSync(r.dir, { recursive: true, force: true }); }
  }
});

test("store snippet: already on the classic store is a no-op; merging keeps unrelated daemon.json keys and is idempotent", () => {
  const a = runSnippet({ store: "classic" });
  try { assert.equal(a.json, null); assert.deepEqual(a.calls, []); } finally { rmSync(a.dir, { recursive: true, force: true }); }
  const orig = JSON.stringify({ "registry-mirrors": ["http://10.20.0.1:5000"], "log-driver": "json-file" });
  const b = runSnippet({ daemonJson: orig });
  try {
    const j = JSON.parse(b.json!);
    assert.deepEqual(j["registry-mirrors"], ["http://10.20.0.1:5000"]);
    assert.equal(j["log-driver"], "json-file");
    assert.equal(j.features["containerd-snapshotter"], false);
  } finally { rmSync(b.dir, { recursive: true, force: true }); }
  const c = runSnippet({ daemonJson: JSON.stringify({ features: { "containerd-snapshotter": false }, x: 1 }), store: "classic" });
  try { assert.deepEqual(JSON.parse(c.json!), { features: { "containerd-snapshotter": false }, x: 1 }); } finally { rmSync(c.dir, { recursive: true, force: true }); }
  const d = runSnippet({ daemonJson: "{not json" });
  try { assert.equal(d.json, "{not json", "an unparsable daemon.json is left alone"); } finally { rmSync(d.dir, { recursive: true, force: true }); }
});

