test("pre-pull guard: fails fast with the clear message when free space is short, passes when it fits, skips when the image is present", () => {
  const run = (freeGB: number, imagePresent: boolean, store: "containerd" | "classic") => {
    const dir = mkdtempSync(join(tmpdir(), "nx-guard-"));
    const bin = join(dir, "bin");
    mkdirSync(bin);
    const w = (n: string, b: string) => { writeFileSync(join(bin, n), `#!/bin/bash\n${b}\n`); chmodSync(join(bin, n), 0o755); };
    w("df", `printf 'Filesystem 1G-blocks Used Available Use%% Mounted on\\n/dev/sda1 40G 1G ${freeGB}G 5%% /\\n'`);
    w("docker", `case "$1" in info) echo '${store === "containerd" ? '[["driver-type","io.containerd.snapshotter.v1"]]' : "[]"}';; image) ${imagePresent ? "exit 0" : "exit 1"};; esac`);
    const script = `nx_state() { echo "$*"; }\nf() {\n${pullDiskGuardShell("left4devops/l4d2:latest", 7, 12)}\n  echo FITS\n}\nf`;
    const r = spawnSync("/bin/bash", ["-c", script], { encoding: "utf8", env: { PATH: `${bin}:/usr/bin:/bin` } });
    rmSync(dir, { recursive: true, force: true });
    return r.stdout.trim();
  };
  assert.equal(run(9, false, "containerd"), "failed: disk too small for this game image: need 12 GB, have 9 GB");
  assert.equal(run(9, false, "classic"), "FITS");
  assert.equal(run(5, false, "classic"), "failed: disk too small for this game image: need 7 GB, have 5 GB");
  assert.equal(run(30, false, "containerd"), "FITS");
  assert.equal(run(2, true, "containerd"), "FITS", "a reinstall with the image already on disk must not be refused");
});
